after.run:
$root = Join-Path $env:GITHUB_WORKSPACE ".prg-live-authority-candidate"
if (Test-Path -LiteralPath $root) { throw "the live-authority candidate root must be fresh: $root" }
npx tsc -p tsconfig.json --outDir "$root\dist"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
node scripts/ci/session-host-windows-acceptance.cjs copy-scripts scripts "$root\scripts"
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
